// The QA round (docs/decisions.md 2026-09-29; docs/testing.md session 30).
const U_QA = "tests/unit/qa.test.ts";
const T_Q_SHEET = "the entry sheet goes in the render the entry line arrives in: it stands only before you're in or while changing (3.24)";
const T_Q_ANSWER = "an answer lands only where it was asked: a late one never moves a step the person has left, or a line they have changed";
const T_Q_ASK = "the steps of asking stand only at asking's own address, and a question is sent once: a second send answers with the draft the first one made";
const T_Q_RETRY = "Try again under a control that has not come back is the same tap again: its own handler, or its form submitted (5.2)";
const T_Q_PLAINLY = "a model that refused a forced tool choice is asked plainly from then on, so the refusal is paid for once";
const T_Q_HANDLE = "a drag that starts on a sheet's handle row is the sheet's alone (3.24, 6.4, 9.9): both rows carry the claim and touch-action none, the claim cancels a touch's move and is never passive, and the close sits outside the row";
const T_Q_PULL = "a pull to re-read starts on the page: a touch that starts in a sheet, pinned or modal, in the ask layer or in a dialog belongs to it (5.5)";
const T_Q_INFO = "the information sheet may reach the top and scrolls as one piece: the name and the fixed line go with the entries, under the sheet's own handle row and close, and the icon never stands above a layer (10.4, 10.5)";
const T_Q_TRAVERSAL = "a traversal is known in one place (9.7): the browser's own flag, else a touch that began at a side edge and was never released to the page; a tap is neither; and it is forgotten once the screen has landed";
const T_Q_STILL = "a screen that lands from a traversal arrives with none of the app's motion, and every arrival reads the one mark (9.7)";
const T_Q_VIEWPORT = "the document never scrolls: the app root is the one scrolling box, the screen's height, and a keyboard is read from the field that takes it";
const T_Q_TOUCH = "a touch on a row fetches its screen whole only while the route is known, and the route's shape otherwise (9.4)";
const T_Q_TALL = "every screen that is the document's own is tall enough to scroll, a root and a task screen alike, and a step inside the ask layer is not (docs/testing.md item 61)";
const T_Q_HOLDS = "the page behind a modal sheet holds still (9.2, 9.9): a sheet whose content fits takes no pan, and one that overflows scrolls itself";
const T_Q_CLOSINGS = "a close chip's word is the word the screen reads back: Tonight ends today and Tomorrow ends tomorrow, a minute before midnight in the asker's zone, whatever the hour; the week and the month are spans (the QA round)";
const T_Q_ZONE = "the viewer's zone is reported from the root on every screen, once per browser: written when the cookie is missing or differs, kept when it agrees, and the one screen drawn before it is drawn again";
const T_Q_TAP = "a tap counts only on the control it began on: a click on a control that rose under the finger is refused, a keyboard's or a script's click always counts, and a press on something gone from the page cannot be judged (the QA round)";
